<script setup>
import {ref,onMounted} from 'vue';import PageHeader from '../../components/student/PageHeader.vue';import {studentApi} from '../../services/studentApi'
const items=ref([]),loading=ref(true),error=ref('');onMounted(async()=>{try{const r=await studentApi.getAssignments();items.value=r.data?.assignments||[]}catch(e){error.value=e.message}finally{loading.value=false}})
</script>
<template><div><PageHeader title="Homework" subtitle="Your assignment and submission status."/><p v-if="loading">Loading homework...</p><p v-else-if="error" class="text-red-500">{{error}}</p><div v-else-if="!items.length" class="card p-8 text-center text-slate-500">No homework assigned.</div><div v-else class="space-y-3"><div v-for="a in items" :key="a.id" class="card p-5 flex flex-col md:flex-row md:items-center md:justify-between gap-3"><div><p class="text-xs text-brand-blue">{{a.subject}}</p><h3 class="font-semibold">{{a.title}}</h3><p class="text-sm text-slate-500">Due {{a.dueDate||'No due date'}} · {{a.status}}</p></div><span class="text-sm font-semibold">{{a.progress}}%</span></div></div></div></template>
